// i18n do portal: pt (padrão), en, es.
// Uso: const L = pickLang(await searchParams); t(L, 'common.sources')

export type Locale = 'pt' | 'en' | 'es';

export function pickLang(searchParams: Record<string, string | string[] | undefined> | undefined | null): Locale {
  const raw = String(searchParams?.lang ?? 'pt').toLowerCase();
  return raw.startsWith('en') ? 'en' : raw.startsWith('es') ? 'es' : 'pt';
}

