  'profile.salary.h': { pt: 'Subsídio mensal', en: 'Monthly salary', es: 'Subsidio mensual' },
  'profile.salary.p.camara': { pt: 'O subsídio mensal dos deputados federais é fixado por resolução da própria Câmara e divulgado em sua área oficial de transparência, junto com a cota parlamentar.', en: 'Federal deputies’ monthly salary is set by resolution of the Chamber itself and published in its official transparency area, along with the expense allowance.', es: 'El subsidio mensual de los diputados federales es fijado por resolución de la propia Cámara y divulgado en su área oficial de transparencia, junto con la cuota parlamentaria.' },
  'profile.salary.p.senado': { pt: 'O subsídio mensal dos senadores é fixado por resolução do próprio Senado e divulgado em sua área institucional de transparência.', en: 'Senators’ monthly salary is set by resolution of the Senate itself and published in its institutional transparency area.', es: 'El subsidio mensual de los senadores es fijado por resolución del propio Senado y divulgado en su área institucional de transparencia.' },
