export type DictKey = keyof typeof VALUES;

export function t(locale: Locale, key: DictKey): string {
  const row = VALUES[key];
  return (row as any)[locale] ?? row.pt;
}

export const LOCALES: { key: Locale; label: string }[] = [
  { key: 'pt', label: 'PT' },
  { key: 'en', label: 'EN' },
  { key: 'es', label: 'ES' },
];
